/**
 * IDNA2008's derived property (RFC 5892 §3) for every code point, generated from Unicode 16.0.
 *
 * GENERATED FILE — do not edit by hand. Regenerate with `npm run gen:idna`.
 *
 * A host name is part of a document's identity (§2.2.1), so whether a U-label is valid must be a
 * property of the document rather than of the runtime. RFC 5892 defines the property as an
 * algorithm over Unicode properties and IANA stopped publishing its values after Unicode 12.0, so
 * the algorithm was run once, at generation, and its result is checked in. The generator checks
 * the result against IANA's Unicode 12.0 table: every code point 12.0 assigns derives to 12.0's
 * value.
 */

/** The Unicode version {@link idnaPropertyCode} and {@link nameClassOf} describe. */
export const IDNA_UNICODE_VERSION = '16.0';

/** {@link idnaPropertyCode}'s result: `DISALLOWED` is zero, so a code point in no range. */
export const IDNA_DISALLOWED = 0;
/** {@link idnaPropertyCode}'s result for RFC 5892's `PVALID`. */
export const IDNA_PVALID = 1;
/** {@link idnaPropertyCode}'s result for RFC 5892's `CONTEXTJ`. */
export const IDNA_CONTEXTJ = 2;
/** {@link idnaPropertyCode}'s result for RFC 5892's `CONTEXTO`. */
export const IDNA_CONTEXTO = 3;
/** {@link idnaPropertyCode}'s result for RFC 5892's `UNASSIGNED`. */
export const IDNA_UNASSIGNED = 4;

/** {@link nameClassOf}'s result for a combining mark: `Mn`, `Mc` or `Me`. */
export const CLASS_COMBINING_MARK = 1;
/** {@link nameClassOf}'s result for a decimal digit: `Nd`. */
export const CLASS_DECIMAL_DIGIT = 2;
/** {@link nameClassOf}'s result for a code point with the `Uppercase` property. */
export const CLASS_UPPERCASE = 3;

const BASE64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Decodes a base64 string to bytes without `atob` or `Buffer`, which this package may not assume. */
function fromBase64(text: string): Uint8Array {
  const lookup = new Int16Array(128).fill(-1);
  for (let i = 0; i < BASE64_ALPHABET.length; i++) {
    lookup[BASE64_ALPHABET.charCodeAt(i)] = i;
  }
  const sextet = (index: number): number => lookup[text.charCodeAt(index)] ?? -1;

  let padding = 0;
  while (padding < 2 && text.charCodeAt(text.length - 1 - padding) === 0x3d /* '=' */) padding++;

  const bytes = new Uint8Array((text.length >> 2) * 3 - padding);
  let out = 0;
  for (let i = 0; i < text.length; i += 4) {
    const a = sextet(i);
    const b = sextet(i + 1);
    const c = sextet(i + 2);
    const d = sextet(i + 3);
    const chunk = (a << 18) | (b << 12) | ((c < 0 ? 0 : c) << 6) | (d < 0 ? 0 : d);
    if (out < bytes.length) bytes[out++] = (chunk >> 16) & 0xff;
    if (out < bytes.length) bytes[out++] = (chunk >> 8) & 0xff;
    if (out < bytes.length) bytes[out++] = chunk & 0xff;
  }
  return bytes;
}

/**
 * Expands a `(gap, width, value)` varint table into a flat `[start, end, value, ...]` array of
 * inclusive ranges. A truncated table yields a short one rather than a crash at module load.
 */
function decodeTable(encoded: string): Uint32Array {
  const bytes = fromBase64(encoded);
  const triples: number[] = [];
  let i = 0;
  let previousEnd = -1;

  const readVarint = (): number => {
    let result = 0;
    let shift = 0;
    for (;;) {
      const byte = bytes[i++];
      if (byte === undefined) return result >>> 0;
      result |= (byte & 0x7f) << shift;
      if ((byte & 0x80) === 0) return result >>> 0;
      shift += 7;
    }
  };

  while (i < bytes.length) {
    const gap = readVarint();
    const width = readVarint();
    const value = readVarint();
    const start = previousEnd + 1 + gap;
    const end = start + width;
    triples.push(start, end, value);
    previousEnd = end;
  }
  return Uint32Array.from(triples);
}

/** Binary search over a flat `[start, end, value, ...]` array; zero for a code point in no range. */
function valueAt(table: Uint32Array, codePoint: number): number {
  let low = 0;
  let high = Math.floor(table.length / 3) - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const start = table[mid * 3];
    const end = table[mid * 3 + 1];
    const value = table[mid * 3 + 2];
    if (start === undefined || end === undefined || value === undefined) return 0;

    if (codePoint < start) {
      high = mid - 1;
    } else if (codePoint > end) {
      low = mid + 1;
    } else {
      return value;
    }
  }
  return 0;
}

/** RFC 5892 derived property (PVALID, CONTEXTJ, CONTEXTO, UNASSIGNED; every other code point is DISALLOWED): 1973 ranges, 6021 bytes encoded. */
const IDNA_PROPERTY = /* @__PURE__ */ decodeTable(
  '',
);

/** Combining marks (Mn, Mc, Me), decimal digits (Nd) and Uppercase code points, as one partition: 1048 ranges, 3200 bytes encoded. */
const NAME_CLASS = /* @__PURE__ */ decodeTable(
  '',
);

/**
 * RFC 5892's derived property of `codePoint`: one of the `IDNA_*` constants. Total over every
 * code point; a lone surrogate, which no well-formed text holds, is `IDNA_DISALLOWED`.
 */
export function idnaPropertyCode(codePoint: number): number {
  return valueAt(IDNA_PROPERTY, codePoint);
}

/**
 * Which of the three general-category classes IDNA's label checks ask about `codePoint` falls in:
 * `CLASS_COMBINING_MARK`, `CLASS_DECIMAL_DIGIT`, `CLASS_UPPERCASE`, or zero for none.
 */
export function nameClassOf(codePoint: number): number {
  return valueAt(NAME_CLASS, codePoint);
}
